    // Check if the message is already stored in the map
    if (messageMap.containsKey(message)) {
        int lastPrintTime = messageMap.get(message);
        // If the current timestamp minus the last print time is greater than or equal to 10
        if (timestamp - lastPrintTime >= 10) {
            // Update the last print time
            messageMap.put(message, timestamp);
            return true;
        } else {
            return false;
        }
    } else {
        // If the message is not in the map, add it with the current timestamp
        messageMap.put(message, timestamp);
        return true;
    }
}

