    if (!ignoreCase) {
        return str.startsWith(prefix);
    } else {
        return toLowerCase(str, prefix);
    }
}

private static boolean toLowerCase(String str, String prefix) {
    for (int i = 0; i < prefix.length(); i++) {
        if (toLowerCaseAscii(str.charAt(i)) != toLowerCaseAscii(prefix.charAt(i))) {
            return false;
        }
    }
    return true;
}

