 * @param tour a set containing the edges of the tour
 * @param graph the graph
 * @return a graph path
 */
protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> path = new LinkedList<>();
    if (tour.isEmpty()) {
        return new GraphPath<>(graph, null, path, 0);
    }

    // Find the starting vertex
    V start = null;
    for (E edge : tour) {
        if (start == null) {
            start = graph.getEdgeSource(edge);
        }
        if (!graph.getEdgeSource(edge).equals(start) && !graph.getEdgeTarget(edge).equals(start)) {
            start = graph.getEdgeSource(edge);
            break;
        }
    }

    if (start == null) {
        return new GraphPath<>(graph, null, path, 0);
    }

    V current = start;
    path.add(current);
    int weight = 0;
    E lastEdge = null;

    while (true) {
        V next = null;
        for (E edge : tour) {
            if (graph.getEdgeSource(edge).equals(current)) {
                next = graph.getEdgeTarget(edge);
                break;
            } else if (graph.getEdgeTarget(edge).equals(current)) {
                next = graph.getEdgeSource(edge);
                break;
            }
        }

        if (next == null) {
            break;
        }

        path.add(next);
        weight += graph.getEdgeWeight(edge);
        lastEdge = edge;
        current = next;
    }

    // If there is a last edge, add it again to close the loop
    if (lastEdge != null) {
        path.add(path.remove(0));
    }

    return new GraphPath<>(graph, null, path, weight);
}

