    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    for (Edge e : graph.edges()) {
        List<Pair<Integer, Integer>> localSeparatorList = new ArrayList<>();

        for (Vertex v : graph.adjacentVertices(e)) {
            List<Vertex> neighborhood = graph.adjacentVertices(v);
            neighborhood.remove(v);
            neighborhood.remove(graph.getOtherVertex(v, e));

            Set<Set<Vertex>> minimalSeparators = new HashSet<>();
            computeMinimalSeparators(neighborhood, new HashSet<>(), new HashSet<>(), minimalSeparators);

            for (Set<Vertex> separator : minimalSeparators) {
                List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
                for (Vertex u : separator) {
                    separatorList.add(new Pair<>(u.getId(), v.getId()));
                }
                localSeparatorList.add(new Pair<>(separatorList, e));
            }
        }

        globalSeparatorList.addAll(localSeparatorList);
    }

    return globalSeparatorList;
}

private void computeMinimalSeparators(List<Vertex> neighborhood, Set<Vertex> currentSeparator, Set<Vertex> visited, Set<Set<Vertex>> minimalSeparators) {
    for (Vertex v : neighborhood) {
        if (visited.contains(v)) continue;

        visited.add(v);
        currentSeparator.add(v);

        boolean isSeparator = true;
        for (Vertex u : neighborhood) {
            if (u.equals(v)) continue;

            if (!currentSeparator.contains(u)) {
                isSeparator = false;
                break;
