        if (isSeparator && !minimalSeparators.contains(currentSeparator)) {
            minimalSeparators.add(new HashSet<>(currentSeparator));
        } else {
            computeMinimalSeparators(neighborhood, currentSeparator, visited, minimalSeparators);
        }

        visited.remove(v);
        currentSeparator.remove(v);
    }
}

