public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    while (true) {
        byte b = read();
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift >= 64) {
            throw new IOException("Too many bytes for a Varint64");
        }
    }
    return result;
}

